sysevent_script_action.script:
// Close the incident that has been on hold for 3+ days
try {
    // Get the assignee information before closing
    var assigneeEmail = '';
    var assigneeName = '';
    var incidentNumber = current.number || '';

    if (current.assigned_to) {
        var assigneeRecord = new GlideRecord('sys_user');
        if (assigneeRecord.get(current.assigned_to)) {
            assigneeEmail = assigneeRecord.email || '';
            assigneeName = assigneeRecord.getDisplayValue() || '';
        }
    }

    // Set resolution information
    current.close_code = 'Closed by System';
    current.close_notes = 'Automatically closed - Incident was on hold for more than 3 days without activity';
    current.state = 7; // Closed state
    current.resolved_at = new GlideDateTime();
    current.closed_at = new GlideDateTime();

    // Update the incident record
    current.update();

    gs.info("Incident " + incidentNumber + " automatically closed after being on hold for 3+ days");

    // Send email notification to assignee if email exists
    if (assigneeEmail && assigneeEmail != '') {
        var email = new GlideEmailOutbound();
        email.setSubject('Incident ' + incidentNumber + ' - Automatically Closed');
        email.setFrom('noreply@servicenow.com');
        email.setTo(assigneeEmail);

        var emailBody = 'Dear ' + assigneeName + ',\n\n';
        emailBody += 'This is to inform you that incident ' + incidentNumber + ' has been automatically closed.\n\n';
        emailBody += 'Reason: The incident was on hold for more than 3 days without any activity.\n\n';
        emailBody += 'If this incident still requires attention, please reopen it or create a new incident.\n\n';
        emailBody += 'Incident Details:\n';
        emailBody += '- Number: ' + incidentNumber + '\n';
        emailBody += '- Short Description: ' + (current.short_description || '') + '\n';
        emailBody += '- Closed At: ' + current.closed_at + '\n\n';
        emailBody += 'Thank you,\nIT Service Desk';

        email.setBody(emailBody);
        email.send();

        gs.info("Notification sent to " + assigneeEmail + " for incident " + incidentNumber);
    } else {
        gs.warn("No assignee email found for incident " + incidentNumber + " - notification not sent");
    }

} catch (e) {
    gs.error("Error processing hold incident closure: " + e.message);
}
